class Resource extends Base {
 mount(){this.options??=[{value:'interaction',label:'Interaction design',group:'Design'},{value:'typography',label:'Typography',group:'Design'},{value:'motion',label:'Motion systems',group:'Design'},{value:'research',label:'User research',group:'Practice'},{value:'accessibility',label:'Accessibility',group:'Practice'},{value:'prototyping',label:'Prototyping',group:'Practice'},{value:'web-components',label:'Web components',group:'Development'},{value:'svg',label:'SVG & illustration',group:'Development'},{value:'performance',label:'Web performance',group:'Development'}];this.chosen=new Set(this._value||[]);this.active=0;this.instanceId=uid();this.render(`<section class="scene panel"><header><span class="label">A FEW THINGS YOU’RE INTO</span><h2>Find your people, your practice.</h2><p class="hint">Search a skill. Keep the things that feel like you.</p></header><label class="field-label" id="${this.instanceId}-label">Areas of interest</label><div class="field"><div class="pills"></div><div class="input-row"><span>⌕</span><input role="combobox" aria-labelledby="${this.instanceId}-label" aria-expanded="false" aria-autocomplete="list" aria-controls="${this.instanceId}-list" placeholder="${escape(this.text('placeholder','Find a skill or topic…'))}" autocomplete="off"/><button class="toggle" aria-label="Show options" tabindex="-1">⌄</button></div></div><div class="options" id="${this.instanceId}-list" role="listbox" aria-label="Areas of interest" aria-multiselectable="true" hidden></div><div class="result"><span class="label">YOUR COLLECTION</span><p aria-live="polite">Nothing selected yet.</p></div></section>`,`.scene{background:var(--bg);min-height:510px;padding:32px;position:relative}h2{font:400 clamp(27px,4vw,37px) Georgia;letter-spacing:-1px;max-width:380px;margin:14px 0}.field-label{display:block;font-size:11px;font-weight:550;color:var(--ink);margin:27px 0 10px}.field{border:1px solid var(--line);border-radius:10px;background:var(--panel);padding:10px 12px}.field:focus-within{border-color:var(--accent)}.pills{display:flex;gap:6px;flex-wrap:wrap}.pill{display:flex;align-items:center;gap:8px;border:1px solid #a9c39433;background:#c6e6b00b;border-radius:5px;padding:5px 6px 5px 9px;color:var(--accent);font-size:10px}.pill button{background:none;border:0;padding:0 3px;color:var(--accent);font-size:15px;line-height:1}.input-row{display:flex;align-items:center;gap:9px}.input-row>span{font-size:23px;color:var(--muted)}input{background:none;border:0;outline:none;flex:1;min-width:0;padding:10px 0;font-size:12px}.toggle{background:none;border:0;color:var(--muted);padding:8px;font-size:18px}.options{position:relative;z-index:2;max-height:215px;overflow-y:auto;border:1px solid var(--line);border-radius:9px;margin-top:7px;padding:6px;background:var(--panel);box-shadow:0 15px 30px #0002}.options[hidden]{display:none}.option{display:flex;align-items:center;justify-content:space-between;padding:10px 11px;border-radius:5px;cursor:pointer;font-size:12px}.option small{display:block;color:var(--muted);font-size:8px;margin-top:4px}.option.active{background:#c6e6b010}.option[aria-selected=true]{color:var(--accent)}.option>span:last-child{font-size:12px;color:var(--accent)}.result{padding-top:24px;margin-top:24px;border-top:1px solid var(--line)}.result p{font-size:12px;color:var(--muted);line-height:1.9;margin-top:10px}@media(max-width:480px){.scene{padding:25px 20px}h2{font-size:29px}.option{font-size:11px}.pill{font-size:9px}}`);const input=this.$('input');this.listen(input,'input',()=>{this.active=0;this.open();});this.listen(input,'focus',()=>this.open());this.listen(input,'keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(this.$('.options').hidden)this.open();else this.active=(this.active+(e.key==='ArrowDown'?1:-1)+this.filtered.length)%Math.max(1,this.filtered.length);this.highlight();}else if(e.key==='Enter'&&!this.$('.options').hidden){e.preventDefault();this.choose(this.active);}else if(e.key==='Escape'){this.close();e.stopPropagation();}else if(e.key==='Backspace'&&!input.value&&this.chosen.size){this.chosen.delete([...this.chosen].at(-1));this.paintValue();this.filter();this.changed();}});this.listen(this.$('.toggle'),'click',()=>{const wasHidden=this.$('.options').hidden;input.focus();wasHidden?this.open():this.close();});this.listen(this.$('.options'),'pointerdown',e=>e.preventDefault());this.listen(this.$('.options'),'click',e=>{const option=e.target.closest('[data-option]');if(option)this.choose(Number(option.dataset.option));});this.listen(this.$('.pills'),'click',e=>{const button=e.target.closest('[data-remove]');if(button){this.chosen.delete(button.dataset.remove);this.paintValue();this.filter();this.changed();input.focus();}});this.listen(document,'pointerdown',e=>{if(!e.composedPath().includes(this))this.close();});this.listen(this.shadowRoot,'focusout',()=>queueMicrotask(()=>{if(!this.shadowRoot.activeElement)this.close();}));this.paintValue();this.filter();}
 get value(){return[...this.chosen||this._value||[]];}
 set value(values){this._value=Array.isArray(values)?values.map(String):[];this.chosen=new Set(this._value);if(this._connected){this.paintValue();this.filter();this.changed();}}
 open(){this.$('.options').hidden=false;this.$('input').setAttribute('aria-expanded','true');this.filter();}
 close(){this.$('.options').hidden=true;this.$('input').setAttribute('aria-expanded','false');this.$('input').removeAttribute('aria-activedescendant');}
 filter(){const q=this.$('input').value.trim().toLowerCase();this.filtered=this.options.filter(o=>`${o.label} ${o.group||''}`.toLowerCase().includes(q));this.active=clamp(this.active,0,Math.max(0,this.filtered.length-1));this.$('.options').innerHTML=this.filtered.length?this.filtered.map((o,i)=>`<div class="option" data-option="${i}" id="${this.instanceId}-${i}" role="option" aria-selected="${this.chosen.has(String(o.value))}"><span>${escape(o.label)}<small>${escape(o.group||'')}</small></span><span aria-hidden="true">${this.chosen.has(String(o.value))?'✓':'+'}</span></div>`).join(''):'<div class="empty">No options match your search.</div>';this.highlight();}
 highlight(){const nodes=this.$$('[role=option]');nodes.forEach((n,i)=>n.classList.toggle('active',i===this.active));if(!this.$('.options').hidden&&nodes[this.active]){this.$('input').setAttribute('aria-activedescendant',nodes[this.active].id);nodes[this.active].scrollIntoView({block:'nearest'});}else this.$('input').removeAttribute('aria-activedescendant');}
 choose(index){const option=this.filtered[index];if(!option)return;const value=String(option.value);this.chosen.has(value)?this.chosen.delete(value):this.chosen.add(value);this.paintValue();this.filter();this.changed();this.$('input').focus();}
 paintValue(){this.$('.pills').innerHTML=[...this.chosen].map(value=>{const item=this.options.find(o=>String(o.value)===value);return`<span class="pill">${escape(item?.label||value)}<button data-remove="${escape(value)}" aria-label="Remove ${escape(item?.label||value)}">×</button></span>`;}).join('');this.$('.result p').textContent=this.chosen.size?[...this.chosen].map(v=>this.options.find(o=>String(o.value)===v)?.label||v).join(' · '):'Nothing selected yet.';}
 changed(){this.emit('value-change',{values:this.value});}
 configured(name){if(name==='placeholder')this.$('input').placeholder=this.text('placeholder','Find a skill or topic…');}
}
